public static partial class KMath
{
    // ---- matrices (kmath/matrix.h) ------------------------------------------------------------------
    public static Mat2 Transpose(Mat2 m) => new Mat2(new Vec2(m.C0.X, m.C1.X), new Vec2(m.C0.Y, m.C1.Y));
    public static Mat2 MatrixCompMult(Mat2 a, Mat2 b) => new Mat2(a.C0 * b.C0, a.C1 * b.C1);
    public static Mat2 OuterProduct(Vec2 column, Vec2 row) => new Mat2(column * row.X, column * row.Y);
    public static Vec2 Row(Mat2 m, int r) => m.Row(r);
    public static Vec2 Column(Mat2 m, int c) => m[c];
    public static Mat2 Row(Mat2 m, int r, Vec2 value)
    {
        m[0, r] = value.X;
        m[1, r] = value.Y;
        return m;
    }
    public static Mat2 Column(Mat2 m, int c, Vec2 value)
    {
        m[c] = value;
        return m;
    }
    public static bool ApproxEqual(Mat2 a, Mat2 b, float epsilon = Epsilon) => ApproxEqual(a.C0, b.C0, epsilon) && ApproxEqual(a.C1, b.C1, epsilon);
    public static Mat2 Diagonal(Vec2 v) => new Mat2(new Vec2(v.X, 0f), new Vec2(0f, v.Y));
    public static float Determinant(Mat2 m) => m.C0.X * m.C1.Y - m.C1.X * m.C0.Y;
    public static Mat2 Inverse(Mat2 m)
    {
        var inv = 1f / Determinant(m);
        return new Mat2(new Vec2(m.C1.Y * inv, -m.C0.Y * inv), new Vec2(-m.C1.X * inv, m.C0.X * inv));
    }
    public static Mat3x2 Transpose(Mat2x3 m) => new Mat3x2(new Vec2(m.C0.X, m.C1.X), new Vec2(m.C0.Y, m.C1.Y), new Vec2(m.C0.Z, m.C1.Z));
    public static Mat2x3 MatrixCompMult(Mat2x3 a, Mat2x3 b) => new Mat2x3(a.C0 * b.C0, a.C1 * b.C1);
    public static Mat2x3 OuterProduct(Vec3 column, Vec2 row) => new Mat2x3(column * row.X, column * row.Y);
    public static Vec2 Row(Mat2x3 m, int r) => m.Row(r);
    public static Vec3 Column(Mat2x3 m, int c) => m[c];
    public static Mat2x3 Row(Mat2x3 m, int r, Vec2 value)
    {
        m[0, r] = value.X;
        m[1, r] = value.Y;
        return m;
    }
